import React, { useState, useEffect } from 'react';
import './WinampTOC.css';

const cleanMarkdownFormatting = (text) => {
  return text
    // Remove bold/italic markers - handle nested formatting like ***text***
    .replace(/\*{1,3}([^*]+)\*{1,3}/g, '$1')
    // .replace(/_{1,3}([^_]+)_{1,3}/g, '$1')
    // // Remove any remaining asterisks or underscores
    // .replace(/[*_]/g, '')
    // Remove code markers
    .replace(/`([^`]+)`/g, '$1')
    // Remove link text but keep description
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    // Remove image tags entirely
    .replace(/!\[[^\]]*\]\([^)]+\)/g, '')
    // Remove HTML tags
    .replace(/<[^>]+>/g, '')
    // Remove any remaining markers
    .replace(/[~`]/g, '')
    // Clean up any double spaces created
    .replace(/\s+/g, ' ')
    .trim();
};

const countWordsInSection = (content, startIndex, level) => {
  const lines = content.split('\n');
  let sectionContent = [];
  let i = startIndex + 1;
  
  while (i < lines.length) {
    const line = lines[i];
    if (line.match(new RegExp(`^#{1,${level}}\\s`))) {
      break;
    }
    sectionContent.push(line);
    i++;
  }
  
  const countWords = (content) => {
    const contentWithoutCode = content.replace(/```[\s\S]*?```/g, '');
    const contentWithoutInlineCode = contentWithoutCode.replace(/`[^`\n]+`/g, '');
    const contentWithoutHtml = contentWithoutInlineCode.replace(/<[^>]*>/g, '');
    const words = contentWithoutHtml.match(/\b[\w']+\b/g);
    return words ? words.length : 0;
  };
  
  return countWords(sectionContent.join('\n'));
};

const createId = (text) => {
  if (!text) return '';
  
  // First convert text to string and trim
  const cleanText = text.toString().trim();
  
  // Create a mapping of special characters to their word equivalents
  const specialCharMap = {
    '+': 'plus',
    '&': 'and',
    '/': 'or',
    '$': 'dollar',
    '@': 'at',
    '%': 'percent',
    '^': 'caret',
    '=': 'equals',
  };
  
  return cleanText
    .toLowerCase()
    // Replace spaces with hyphens first
    .replace(/\s+/g, '-')
    // Replace special characters with their word equivalents
    .replace(/[+&/$@%^=]/g, match => `-${specialCharMap[match]}-`)
    // Remove any other special characters
    .replace(/[^a-z0-9-]/g, '')
    // Clean up multiple consecutive hyphens
    .replace(/-+/g, '-')
    // Remove hyphens from start and end
    .replace(/^-+|-+$/g, '');
};

// This is a react component that implements a TOC that looks like the Winamp track selector
const WinampTOC = ({ markdownContent }) => {
  const [toc, setToc] = useState(null);
  const [selectedIndex, setSelectedIndex] = useState(1);

  const scrollToHeader = (targetId) => {
    const header = document.getElementById(targetId);
    
    if (!header) return;
  
    // Smooth scroll to the header
    header.scrollIntoView({ 
      behavior: 'smooth', 
      block: 'start'
    });
  
    // Add highlight animation class
    header.classList.add('header-highlight');
    
    // Remove highlight after animation
    header.addEventListener('animationend', () => {
      header.classList.remove('header-highlight');
    }, { once: true });
  };

  useEffect(() => {
    function generateTOC() {
      try {
        const lines = markdownContent.split('\n');
        const headers = [];
        let insideCodeBlock = false;

        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          
          if (line.trim().startsWith('```')) {
            insideCodeBlock = !insideCodeBlock;
            continue;
          }

          if (!insideCodeBlock) {
            const headerMatch = line.match(/^(#+)\s+(.*)/);
            
            if (headerMatch) {
              const level = headerMatch[1].length;
              const rawText = headerMatch[2].trim();
              const cleanText = cleanMarkdownFormatting(rawText);
              
              if (level < 4) {
                const words = countWordsInSection(lines.join('\n'), i, level);
                // Use the clean text for ID generation
                const id = createId(cleanText);
                // Use the clean text for display in TOC
                headers.push({ level, text: cleanText, words, id });
              }
            }
          }
        }

        const tocItems = headers.map((header, index) => {
          const isSelected = selectedIndex === index + 1;
          const indent = (header.level - 1) * 2;

          return (
            <a
              key={`${index}-${header.text}`}
              href={`#${header.id}`}
              className={`winamp-playlist-item ${isSelected ? 'selected' : ''}`}
              style={{
                paddingLeft: `${indent}em`
              }}
              onClick={(e) => {
                e.preventDefault();
                setSelectedIndex(index + 1);
                scrollToHeader(header.id);
              }}
            >
              <span className="winamp-item-number">{index + 1}.</span>
              <span className="winamp-item-title">{header.text}</span>
              <span className="winamp-word-count">{header.words}</span>
            </a>
          );
        });

        setToc({ items: tocItems });
      } catch (error) {
        console.error("Error generating TOC:", error);
      }
    }

    generateTOC();
  }, [markdownContent, selectedIndex]);

  return (
    <div className="winamp-container">
      <div className="winamp-title-bar">
        <div className="winamp-yellow-bars-group">
          <div className="winamp-yellow-bar-big" />
          <div className="winamp-yellow-bar-small" />
        </div>
        
        <span className="winamp-title-text">TABLE OF CONTENTS</span>
        
        <div className="winamp-yellow-bars-group">
          <div className="winamp-yellow-bar-big" />
          <div className="winamp-yellow-bar-small" />
        </div>
      </div>
      
      <div className="winamp-playlist">
        {toc?.items}
      </div>
    </div>
  );
};

export default WinampTOC;